style.css:
@-moz-document domain("playerok.com") {
/* ==== ОБЩИЕ НАСТРОЙКИ ==== */
body {
  background: linear-gradient(145deg, #0f0f0f, #1c1c1c);
  font-family: 'Segoe UI', sans-serif;
  color: #e0e0e0;
  transition: all 0.3s ease-in-out;
}

/* ==== СКРОЛЛБАР ==== */
::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: #1c1c1c;
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #00f2ff, #8a2be2);
  border-radius: 10px;
}

/* ==== КНОПКИ ==== */
button, .btn, input[type="submit"] {
  background: linear-gradient(135deg, #00f2ff, #8a2be2);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 10px 16px;
  font-weight: bold;
  transition: transform 0.2s ease, box-shadow 0.3s ease;
}
button:hover, .btn:hover, input[type="submit"]:hover {
  transform: scale(1.05);
  box-shadow: 0 0 15px #8a2be2;
}

/* ==== ХЕДЕР ==== */
header, .navbar, .topbar {
  background: rgba(20, 20, 20, 0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

/* ==== КАРТОЧКИ ==== */
.card, .product-card, .item-box, .item {
  background: rgba(30, 30, 30, 0.9) !important;
  border-radius: 16px !important;
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 0 25px rgba(0, 255, 255, 0.05);
  transition: all 0.3s ease-in-out;
}
.card:hover, .product-card:hover, .item-box:hover {
  box-shadow: 0 0 20px #00f2ff50, 0 0 5px #8a2be250;
  transform: scale(1.02);
}

/* ==== ИНПУТЫ ==== */
input[type="text"], input[type="email"], input[type="password"], textarea, select {
  background: #1e1e1e;
  border: 1px solid #333;
  border-radius: 10px;
  color: #fff;
  padding: 8px 12px;
  transition: all 0.2s ease-in-out;
}
input:focus, textarea:focus, select:focus {
  border-color: #8a2be2;
  box-shadow: 0 0 5px #8a2be2;
}

/* ==== ССЫЛКИ ==== */
a {
  color: #00f2ff;
  transition: color 0.2s ease-in-out;
}
a:hover {
  color: #8a2be2;
}

/* ==== АНИМАЦИЯ ПРИ НАВЕДЕНИИ ==== */
.card, .btn, .product-card {
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

/* ==== ПРИЛОЖЕНИЕ К ВЫБРАННЫМ СТРАНИЦАМ ==== */
.main-content, .container, .content {
  padding: 20px;
}
}
